    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[j] + 1 === arr[i] || arr[j] - 1 === arr[i]) {
                dp[i] = Math.max(dp[i], 1 + dp[j]);
            }
        }
    }
    let result = 1;
    for (let i = 0; i < n; i++) {
        if (result < dp[i]) {
            result = dp[i];
        }
    }
    return result;
}

