    private void backtrack(List<List<Integer>> result, List<Integer> current, int n, int k) {
        if (current.size() == k) {
            result.add(new ArrayList<>(current));
            return;
        }

        for (int i = 1; i <= n; i++) {
            if (i > k) {
                break;
            }
            current.add(i);
            backtrack(result, current, n, k);
            current.remove(current.size() - 1);
        }
    }
}

