                double priceB = Double.parseDouble(b[1]);

                // Compare the double values
                if (priceA < priceB) {
                    return -1;
                } else if (priceA > priceB) {
                    return 1;
                } else {
                    // If prices are equal, keep them in the same order
                    return 0;
                }
            }
        });

        return price;
    }
}

