class Solution {
    public int[] heapQueueSmallest(int[] nums, int n) {
        // Use PriorityQueue to store the smallest numbers in a max-heap
        PriorityQueue<Integer> minHeap = new PriorityQueue<>(Collections.reverseOrder());

        // Add all elements to the priority queue
        for (int num : nums) {
            minHeap.offer(num);
        }

        // Extract the smallest n elements from the priority queue
        int[] smallestNums = new int[n];
        for (int i = 0; i < n; i++) {
            smallestNums[i] = minHeap.poll();
        }

        return smallestNums;
    }
}

