    public static String removeWhitespaces(String text1) {
        // Use a regular expression to match all whitespace characters
        Pattern pattern = Pattern.compile("\\s+");
        Matcher matcher = pattern.matcher(text1);

        // Create a StringBuilder to build the result
        StringBuilder result = new StringBuilder();

        // Iterate over each character in the text
        while (matcher.find()) {
            // Append the matched character to the result
            result.append(matcher.group());
        }

        // Return the resulting string without whitespaces
        return result.toString();
    }

    public static void main(String[] args) {
        // Example usage
        String input = "  Hello, World!  ";
        String output = removeWhitespaces(input);
        System.out.println(output);  // Output: HelloWorld!
    }
}

