    public static int next_Power_Of_2(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("Input must be a positive integer.");
        }

        int count = 0;
        while (n > 0 && 0 == (n & (n - 1))) {
            count++;
            n >>= 1;
        }

        return (1 << count);
    }
}

