        while (gaps > 1 || swapped) {
            gaps = (int) (gaps / shrinkFact);
            swapped = false;
            i = 0;
            while (gaps + i < nums.length) {
                if (nums[i] > nums[i + gaps]) {
                    int temp = nums[i];
                    nums[i] = nums[i + gaps];
                    nums[i + gaps] = temp;
                    swapped = true;
                }
                i += 1;
            }
        }
        return nums;


