function longest_common_subsequence(X, Y, m, n) {
    if (m == 0 || n == 0) {
        return 0;
    } else if (X[m - 1] === Y[n - 1]) {
        return 1 + longest_common_subsequence(X, Y, m - 1, n - 1);
